@Tags(['golden'])
library;

// T-174 (batch 21): goldens for screens that had none. ar/en x light/dark at
// scale 1.0. PNGs are generated by CI (`--update-goldens`), never committed.

import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:zaghlol/core/l10n/date_format.dart';

import '../support/golden_matrix.dart';
import 'a11y_pumps.dart';

Future<void> main() async {
  await initDateFormatting();
  final screens = <String, Future<void> Function(WidgetTester, GoldenVariant)>{
    'account': pumpAccountS69,
    'edit_budgets': pumpEditBudgets,
    'insights_shell': pumpInsightsShell,
    'template_builder': pumpTemplateBuilder,
    'lock': pumpLock,
    'passphrase_sheet': pumpPassphraseSheet,
    'home_card_filter_sheet': pumpHomeCardFilterSheet,
  };
  for (final v in goldenVariants) {
    screens.forEach((name, pump) {
      testWidgets('$name golden ${v.name}', (t) async {
        await pump(t, v);
        await expectLater(
          find.byType(MaterialApp),
          matchesGoldenFile('goldens/${name}_${v.name}.png'),
        );
      });
    });
  }
}
